--
-- Name: collections_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.collections_effective AS
 SELECT do_no,
    source,
    job_no,
    do_date,
    do_type,
    trip_type,
    site_id,
    vessel_name,
    berth,
    vehicle_id,
    driver_id,
    job_type,
    waste_type,
    bin_in,
    bin_out,
    vol_cat_a,
    vol_cat_b,
    vol_cat_c,
    vol_cat_d,
    vol_cat_e,
    vol_cat_f,
    vol_total_m3,
    gross_kg,
    tare_kg,
    net_kg,
    weigh_ticket_no,
    weigh_location,
    weight_source,
    gps_lat,
    gps_lng,
    gps_accuracy_m,
    gps_captured_at,
    photo_do_ref,
    photo_sig_ref,
    photo_weigh_ref,
    receipt_ref,
    disposal_facility,
    xero_invoice_id,
    backfill_notes,
    synced_at,
    COALESCE(( SELECT (a.new_value)::numeric AS new_value
           FROM public.adjustments a
          WHERE ((a.do_no = c.do_no) AND (a.field = 'net_kg'::text))
          ORDER BY a.adjusted_at DESC
         LIMIT 1), net_kg) AS net_kg_effective,
    COALESCE(( SELECT (a.new_value)::numeric AS new_value
           FROM public.adjustments a
          WHERE ((a.do_no = c.do_no) AND (a.field = 'vol_total_m3'::text))
          ORDER BY a.adjusted_at DESC
         LIMIT 1), vol_total_m3) AS vol_total_m3_effective
   FROM public.collections c;


